B='026多了一个.txt'
make('shensuofu_bu','申索夫／新的卜连昌',B,
'这个获救者认为自己是海员卜连昌，熟知船员私事、彩珍和两个孩子的生活，却没有一个熟人承认他的脸。他的困境不是装出来的身份游戏：镜中的自己在他看来十分自然，照片里应有的位置却坐着别人，所谓妻儿也把他当陌生人。他在失望中撞断门链、闯入船公司，又被卫斯理收留，先做不称职的普通工作，后来意外表现出熟练操纵先进电脑的能力。苏联来人用照片与旧枪伤证实这具身体属于太空飞行员申索夫上校，他却连有关过去的语言和经历都无法按要求想起。卫斯理综合专家意见，提出危急时不同人的脑电波记忆互相干扰的假说；这是解释，不是已经实验验证的灵魂移植。终局来人同意放弃追索，他选择接受现在的自己，在卫斯理公司工作，并重新赢得彩珍与孩子们的好感，准备以求婚而非原丈夫权利进入家庭。此卡采用这种最后身份与知识状态，保留实际展示的电脑技能和异常取得的记忆，不把旧军阶等同仍能调用航天系统、导弹或国家机密。人物成长的核心是从强求别人承认过去，转为凭现在的行动建立关系。',
'追索者撤回，继续在卫斯理公司任职，并准备向彩珍求婚；尚未写出婚礼。','保留的电脑专长与异常记忆','熟练操作当时公司的新型电脑；拥有卜连昌及遇险船员的部分记忆，来源为小说内假说。','不能主动读取或转移记忆，也不能据旧上校身份恢复全部军用技能和资源；亲属记忆不产生他人必须认可的身份权。',[(350,451,'记忆与家属不认'),(674,770,'实际电脑技能'),(929,960,'照片、枪伤及逃离'),(1032,1088,'旧太空任务和逃生信息'),(1337,1369,'记忆假说与新生活')],
'让眼下的技能、选择和关系构成可生活的身份。',[('别人否认他的自我经历','对方有可靠照片或证人','承受冲击后核对证据，不强行宣称所有人都在说谎。'),('技术任务引出熟悉感觉','已经能实际操作','以结果证明技能，同时承认不知道学习来源。'),('想接近彩珍与孩子','他们仍有独立意愿','以新的关系争取信任，接受拒绝而不主张旧婚姻自动有效。')],aliases=('申索夫上校','自称卜连昌的获救者'),scores=(2,0,1,2,1,2),tier='并',durability='常人体质，左肩有旧枪伤疤；没有太空事故免疫。',uncertainties=('脑电波替换和混合只属卫斯理综合后的解释。','终局保留电脑技能，但无法确定全部旧专业知识清单。'))
make('bu_lianchang_original','卜连昌（原海员）',B,
'原来的卜连昌是一名做过三副的海员，彩珍的丈夫，也是阿牛、阿珠的父亲。他与后来从海中被救起、长着申索夫面孔的人不是同一具身体，原文通过家属照片、船长认识和死亡通知反复区分。顾船长记得他喝酒好事，听到他的名字会头痛；家人的资料则留下另一个侧面，他会给孩子买西游记泥娃娃，也与妻子拥有初次相见的私人记忆。这些生活事实后来被陌生人准确说出，使彩珍惊恐，也让调查者难以只用假冒解释。卜连昌在南美洲港口与人冲突后被杀害，详细凶手和过程没有稳定身份资料，不能补出新的仇家卡。他已经死亡的事实与记忆似乎存续于别人脑中并不等同本人复活：卫斯理提出的是记忆干扰假说，新获救者还混有其他船员的片段，不能把后者所有能力反送给死去的海员。综合参战若恢复本人的最后行动形态，应该是有海上经验、家庭牵挂和酒后冲动问题的普通人，不具申索夫的电脑特长或航天身份。面对同名的新人物，他可以因家属与身份边界产生复杂反应，却必须承认亲人有权依现实经历建立新的关系。',
'在南美洲港口遭杀害，照片确认与获救的申索夫不同。','海员经验与家庭生活记忆','具有做三副的职业经历和对家庭的熟悉；没有独立超常表现。','已经死亡；记忆被他人拥有不等于本人可附体、重生或读心，不能继承申索夫电脑技能。',[(85,89,'船长对原海员的认识'),(350,388,'子女记忆及死亡通知'),(415,451,'本人照片和夫妻往事'),(1337,1353,'死前冲突和记忆假说')],
'保全家人与海员生活，同时处理酒后冲动带来的代价。',[('与人因酒或面子争执','局面正在升级','先识别撤退机会，不能凭粗壮身体保证活着离开。'),('家属需要实际照顾','有可用收入和时间','以具体照顾回应，而不只要求家庭认可。'),('有人拥有他的私人记忆','对方身体和经历不同','核对细节与界限，不把记忆相似直接视为夺舍。')],dead=True,scores=(2,0,0,2,1,1),tier='并',roles=('前史主线人物',),uncertainties=('主要由照片、家人和船长回忆构成，心理细节不作额外确定化。',))
make('caizhen','彩珍',B,
'彩珍是原海员卜连昌的妻子，独自照顾阿牛和阿珠。故事开始时，她刚收到丈夫在南美洲遇害的通知，满面悲伤，还没有勇气把父亲死亡告诉孩子。一名脸孔、声音全然陌生的男子冲进住处喊她名字，自称已经回家，她的拒认有直接而充分的现实理由，不能被当成缺乏感情。她向卫斯理拿出家庭合照，说明真正丈夫的样子，又在陌生人说出初见时的衣服和头绳后发抖；准确记忆使事情更惊人，却没有迫使她放弃自己对人的辨识。此后新卜连昌在住所附近徘徊、送孩子礼物，她起初仍受惊并拒绝接触，正文最后才写他经过几个月取得她和孩子的好感，准备求婚。这个变化是新的关系逐渐建立，并非旧婚姻自然移交给另一具身体，也没有写到她已经答应婚事。综合卡保留丧偶、育儿与重建生活的连续性，给她自己判断信任的空间。她没有因为处在异常事件中心而拥有读心或辨魂能力，只能结合照片、相处、言行和自身感受作决定。遇到解释再奇特的来客，她也可以要求距离和可靠帮助，而不需要立刻配合对方的人生叙事。',
'几个月后对新的卜连昌产生好感，对方准备求婚，婚姻是否达成未写。','家庭记忆核验与关系判断','用照片、声音、相处和家庭事实判断来者身份，逐步建立或拒绝信任。','无辨魂、读心等超常能力；他人知道私密事实不等于她必须承认配偶身份。',[(365,393,'悲伤与拒认'),(409,451,'照片和初见记忆'),(658,664,'初期畏惧与徘徊'),(1363,1370,'终局好感和求婚准备')],
'照护孩子，并在失去丈夫后以自己的节奏决定未来关系。',[('陌生人宣称是亲属','脸孔声音不符','保持距离，核对事实并寻求帮助。'),('对方提供准确旧记忆','身份仍无法确认','承认细节可靠，同时不放弃自己的判断。'),('新的相处逐渐值得信任','自身与孩子均感安全','允许新的关系发展，保留同意或拒绝的权利。')],scores=(1,0,0,1,1,1),tier='纸',aliases=('卜太太',))
make('shensuofu_pursuers','追索申索夫的考察团长与助手',B,
'这两名以东南亚贸易考察团身份行动的苏联安全人员，实际任务是找到失踪太空飞行员申索夫。团长以军阶、照片和旧伤记录识别目标，助手补充其安全部门身份并参与拘捕。他们起初把否认与不会认出旧身份当成伪装，以国家叛徒和制裁相威胁，甚至动手抓住对方衣服，反而逼得他逃出卫斯理公司。面对当地独立行动者，他们不能仅靠外交头衔实现逮捕，随后必须请示莫斯科并披露原本严守的太空飞行秘密，争取卫斯理帮助。这一转变说明二人虽强硬，仍会根据任务失败和上级要求改变手段。最后他们听到关于异常记忆的解释，承认可能合理，却担心无法向上级报告；当卫斯理提出把现有的人视为已经不再掌握秘密的另一人时，二人经过考虑决定停止追索。此后没有继续骚扰的行为。综合卡应保留他们的调查、档案和组织联络优势，也保留以国家目的压过个人意愿的风险；同时不能把所有苏联军事资源、申索夫的太空船和导弹当成二人的随身能力。终局的有限让步提供了可被说服的接口，不等于政治立场彻底改变。',
'接受解释并放弃追索，之后未再干扰新卜连昌生活。','档案核验、组织联络与拘捕施压','以照片、伤疤记录、外交掩护和上级通讯追查人员；具普通近身拘捕手段。','无法自动在他国合法或实际控制所有人，动手会导致目标逃跑；上级资源需要批准，旧太空设备不归本人。',[(845,862,'威胁和拘捕'),(881,960,'身份、档案与目标逃离'),(1004,1047,'请示及秘密披露'),(1330,1366,'听取解释并停止')],
'完成人员与机密保护任务，并找到能向上级交代的现实方案。',[('档案与当事人记忆冲突','生理身份确证而行为不符','先核对矛盾，不直接把全部失忆认定为叛逃。'),('强制行动造成逃离','地方协助者拒绝配合','转向解释与协商，明确可披露信息。'),('目标已不掌握原秘密','继续追索成本高且缺乏理由','提出可被组织接受的收尾办法，允许停止任务。')],roles=('阶段性对立者','明确身份双人组'),scores=(2,0,1,3,2,3),tier='强')
cov(B,[('白素','weisili_bai_su','跨书重要配角','提出照片核验等帮助。'),('新的卜连昌','shensuofu_bu','单书主角','申索夫身体与新记忆身份。'),('原卜连昌','bu_lianchang_original','前史主线人物','死亡及记忆来源，与新人物分开。'),('彩珍','caizhen','单书主角','家属辨识、丧偶和新关系。'),('团长与助手','shensuofu_pursuers','阶段性对立者','追索、拘捕和最终让步。')],[('顾船长、船员、公司经理、德国工程师','目击、职务和技术核验的一次性辅助，未见独立主角或反派线。'),('阿牛、阿珠、包医师夫妇','家庭识别和关系发展辅助，不把受惊拒绝陌生人列为反派。'),('南美洲冲突凶手','没有稳定姓名或个体身份，死亡前史未提供可成卡的行为线。'),('考察团其他人员及会诊专家','未形成独立身份弧，所提供背景并入相应人物。')],['两名卜连昌分卡；异常记忆假说与已验证电脑能力分开，终局不能自动恢复全部太空员秘密。'])
